fn clip(arr: &Vec<i8>, min_val: i8, max_val: i8) -> Vec<i8> {
    let len = arr.len();
    // If the provided lower bound is greater than the upper bound,
    // return a vector filled with max_val of the same length.
    if min_val > max_val {
        return vec![max_val; len];
    }

    // Otherwise, clamp each element into the inclusive range [min_val, max_val].
    let mut result = Vec::with_capacity(len);
    for &x in arr {
        let clipped = if x < min_val {
            min_val
        } else if x > max_val {
            max_val
        } else {
            x
        };
        result.push(clipped);
    }

    result
}

